--
-- Structure de la table `batches`
--

DROP TABLE IF EXISTS `batches`;
CREATE TABLE IF NOT EXISTS `batches` (
  `id` int NOT NULL AUTO_INCREMENT,
  `recipe_id` int NOT NULL,
  `batch_count` int NOT NULL DEFAULT '1',
  `date` date NOT NULL,
  `formula` varchar(255) NOT NULL,
  `code_plat` varchar(100) DEFAULT '',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `loss_percent` decimal(5,2) DEFAULT '0.00',
  `pieces_produced` int DEFAULT NULL,
  `leftovers_kg` decimal(10,3) DEFAULT NULL,
  `inventory_type` enum('semi-final','final') DEFAULT 'semi-final',
  PRIMARY KEY (`id`),
  KEY `recipe_id` (`recipe_id`)
) ENGINE=MyISAM AUTO_INCREMENT=177 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

